DO $test$ DECLARE ownerid uuid:='e7100000-0000-4000-8000-000000000001'; reviewer uuid:='e7100000-0000-4000-8000-000000000002'; BEGIN BEGIN INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(ownerid,'step7-owner@example.invalid','{}'),(reviewer,'step7-rev@example.invalid','{}');UPDATE public.user_roles SET role='owner' WHERE user_id=ownerid;INSERT INTO public.hiring_user_roles(user_id,role) VALUES(reviewer,'reviewer');PERFORM set_config('request.jwt.claim.sub',ownerid::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',ownerid,'role','authenticated')::text,true);SET LOCAL ROLE authenticated;IF NOT public.has_role(ownerid,'admin') THEN RAISE EXCEPTION 'Owner not synced';END IF;BEGIN PERFORM public.revoke_hiring_role(ownerid,'admin');RAISE EXCEPTION 'Owner revoke allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Owners keep admin automatically and cannot be revoked here' THEN RAISE;END IF;END;RESET ROLE;PERFORM set_config('request.jwt.claim.sub',reviewer::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'role','authenticated')::text,true);SET LOCAL ROLE authenticated;BEGIN PERFORM public.hiring7_move_journey('e7100000-0000-4000-8000-000000000003','learner','',false);RAISE EXCEPTION 'Reviewer journey move allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;RESET ROLE;RAISE EXCEPTION 'step7_owner_rollback' USING ERRCODE='Z0001';EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;END;IF EXISTS(SELECT 1 FROM auth.users WHERE id IN(ownerid,reviewer)) THEN RAISE EXCEPTION 'Owner fixtures remain';END IF;END $test$;